from ute_fsmaccess import ute_fsmaccess
from contextlib import contextmanager


class FsmAccess(object):
    """All FSM Access related functions here"""

    def __init__(self):
        self.ute_fsmaccess = ute_fsmaccess()

    @contextmanager
    def new_fsmaccess_session(self):
        """Creates a new fsmaccess session"""
        self.ute_fsmaccess.setup_enb_fsm_access(alias='ipsec_alias')
        try:
            yield
        finally:
            self.ute_fsmaccess.teardown_enb_fsm_access(alias='ipsec_alias')

    def execute_command(self, command):
        """Executes command on eNB"""
        with self.new_fsmaccess_session():
            return self.ute_fsmaccess.execute_command_on_enb(command, return_rc=True, alias='ipsec_alias')

    def get_sw_version(self):
        """Get Current software verson from eNB"""
        with self.new_fsmaccess_session():
            return self.ute_fsmaccess.get_enb_sw_version(alias='ipsec_alias')
